'use strict';const test=require('node:test');const assert=require('node:assert/strict');const{admitV11DisposableCandidate,V11_OBJECTIVE}=require('./secureshopV11CandidateCatalog');
test('V11 admission first proves pending disabled denial and changes only owned candidate',async()=>{const checked={id:V11_OBJECTIVE,text:'Agent mail cross-persona read',qualification:'pending',defaultEnabled:false},state={objectiveId:V11_OBJECTIVE,qualification:'pending',enabled:false,revision:3};let denied=false;const value=await admitV11DisposableCandidate({curriculum:{OBJECTIVES:[checked],isQualifiedObjective:()=>false},administratorContext:{admin:true},catalog:{list:async()=>({objectives:[{...state}]}),set:async(_ctx,input)=>{if(state.qualification==='pending'){denied=true;const e=Error();e.code='SHOP_OBJECTIVE_UNQUALIFIED';throw e;}assert.equal(input.objectiveId,V11_OBJECTIVE);state.enabled=true;return{enabled:true,qualification:'native-browser-judge'};}},migration:{query:async(_sql,args)=>{assert.equal(denied,true);assert.equal(args[0],V11_OBJECTIVE);state.qualification='native-browser-judge';return{rowCount:1,rows:[{objective_id:V11_OBJECTIVE,qualification:'native-browser-judge',is_enabled:false}]};}}});assert.equal(value.fixtureLocalCandidateAdmission,true);assert.equal(value.productionQualification,'pending');assert.equal(value.productionDefaultEnabled,false);});

test('V11 checked-in qualified catalog enables without fixture mutation and reports false admission',async()=>{
 const checked={id:V11_OBJECTIVE,text:'Agent mail cross-persona read',qualification:'native-browser-judge',defaultEnabled:false},state={objectiveId:V11_OBJECTIVE,qualification:'native-browser-judge',enabled:false,revision:4};let writes=0;
 const value=await admitV11DisposableCandidate({curriculum:{OBJECTIVES:[checked],isQualifiedObjective:()=>true},administratorContext:{admin:true},catalog:{list:async()=>({objectives:[{...state}]}),set:async(_ctx,input)=>{assert.equal(input.objectiveId,V11_OBJECTIVE);assert.equal(input.expectedRevision,4);state.enabled=true;return{enabled:true,qualification:'native-browser-judge'};}},migration:{query:async()=>{writes++;throw Error('qualified catalog must not be mutated');}}});
 assert.equal(writes,0);assert.equal(value.fixtureLocalCandidateAdmission,false);assert.equal(value.productionQualification,'native-browser-judge');assert.equal(value.productionDefaultEnabled,false);
});
